CREATE FUNCTION public.guard_task_order_settlement() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='success' AND OLD.status<>'success' AND (OLD.status<>'pending' OR OLD.expires_at<=now()) THEN RAISE EXCEPTION 'Checkout expired; payment requires admin review'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_task_order_settlement BEFORE UPDATE OF status ON public.task_nft_orders FOR EACH ROW EXECUTE FUNCTION public.guard_task_order_settlement();
CREATE FUNCTION public.settle_task_nft_verified(_reference text,_paid_kobo bigint) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record; BEGIN SELECT * INTO p FROM public.task_nft_orders WHERE reference=_reference FOR UPDATE; IF p.id IS NULL THEN RETURN 'not_found'; END IF; IF p.status='success' THEN RETURN 'already'; END IF; IF p.status<>'pending' OR p.expires_at<=now() THEN UPDATE public.task_nft_orders SET status='needs_review',verified_at=now() WHERE id=p.id; RETURN 'needs_review'; END IF; RETURN public.fulfill_task_nft_payment(_reference,_paid_kobo); END $$;
REVOKE ALL ON FUNCTION public.settle_task_nft_verified(text,bigint) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.settle_task_nft_verified(text,bigint) TO service_role;
ALTER TABLE public.crypto_nft_checkouts ADD CONSTRAINT crypto_nft_status CHECK(status IN('pending','success','needs_review','failed'));
CREATE FUNCTION public.prepare_crypto_nft_checkout(_user uuid,_nft uuid,_wallet text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q json; p record; c uuid; BEGIN IF _wallet !~ '^0x[0-9a-fA-F]{40}$' THEN RAISE EXCEPTION 'Invalid wallet'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user AND NOT marketplace_blocked) THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.crypto_nft_checkouts c JOIN public.payments p ON p.id=c.payment_id WHERE c.user_id=_user AND c.status='pending' AND p.quote_expires_at>now()) THEN RAISE EXCEPTION 'Finish or wait for your pending wallet checkout to expire'; END IF; q:=public.prepare_checkout_for_user(_user,'nft',_nft,NULL,1); SELECT * INTO p FROM public.payments WHERE reference=q->>'reference'; INSERT INTO public.crypto_nft_checkouts(payment_id,user_id,wallet_address,amount_usdt) VALUES(p.id,_user,lower(_wallet),p.amount_usd) RETURNING id INTO c; RETURN json_build_object('id',c,'amount',p.amount_usd,'expires_at',p.quote_expires_at); END $$;
CREATE FUNCTION public.settle_crypto_nft_verified(_id uuid,_user uuid,_hash text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; p record; r text; BEGIN IF _hash !~ '^0x[0-9a-fA-F]{64}$' THEN RAISE EXCEPTION 'Invalid transaction'; END IF; SELECT * INTO c FROM public.crypto_nft_checkouts WHERE id=_id AND user_id=_user FOR UPDATE; IF c.id IS NULL THEN RAISE EXCEPTION 'Checkout not found'; END IF; IF c.status='success' THEN IF c.tx_hash=lower(_hash) THEN RETURN 'already'; ELSE RAISE EXCEPTION 'Checkout already settled'; END IF; END IF; SELECT * INTO p FROM public.payments WHERE id=c.payment_id FOR UPDATE; UPDATE public.crypto_nft_checkouts SET tx_hash=lower(_hash) WHERE id=c.id; IF c.status<>'pending' OR p.status<>'pending' OR p.quote_expires_at<=now() THEN UPDATE public.crypto_nft_checkouts SET status='needs_review' WHERE id=c.id; UPDATE public.payments SET status='needs_review',verified_at=now() WHERE id=p.id; RETURN 'needs_review'; END IF; r:=public.fulfill_payment(p.reference,p.amount_ngn_kobo); UPDATE public.crypto_nft_checkouts SET status=CASE WHEN r IN ('ok','already') THEN 'success' ELSE 'needs_review' END WHERE id=c.id; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.prepare_crypto_nft_checkout(uuid,uuid,text),public.settle_crypto_nft_verified(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prepare_crypto_nft_checkout(uuid,uuid,text),public.settle_crypto_nft_verified(uuid,uuid,text) TO service_role;